def round_half_to_even(n):
    """Rounds a number to the nearest integer, rounding half to even (bankers' rounding).

    Args:
        n (float): The number to round.

    Returns:
        int: The rounded number.
    """
    if not isinstance(n, (int, float)):
        raise TypeError("Input must be a number")

    if n >= 0:
        return int(n + 0.5 - 0.5 * (n % 1 == 0.5))
    else:
        return int(n - 0.5 + 0.5 * (n % 1 == -0.5))

def round_half_to_even(n):
    """
    Rounds a number to the nearest integer, rounding halfway cases away from zero.

    :param n: The number to round
    :return: The rounded number
    """
    if not isinstance(n, (int, float)):
        raise TypeError("Input must be a number")

    if n >= 0:
        return int(n + 0.5)
    else:
        return int(n - 0.5)

def round_half_to_even(n):
    """
    Rounds a number to the nearest integer, rounding half to the nearest even number.

    :param n: The number to round
    :return: The rounded integer
    """
    if not isinstance(n, (int, float)):
        raise TypeError("Input must be a number")

    if n == int(n):
        return n

    fractional_part = n - int(n)
    if abs(fractional_part - 0.5) < 0.00001:
        return int(n) + (int(n) % 2)
    else:
        return round(n)

def round_half_to_even(n):
    """
    Round the given number to the nearest integer, rounding halfway cases to the nearest even number.

    :param n: The number to round
    :return: The rounded number
    """
    if n % 1 == 0.5 or n % 1 == -0.5:
        return int(n) + (int(n) % 2)  # Round halfway cases to the nearest even number
    else:
        return round(n)
