def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """

    import sys
    from types import MethodType

    class Point:
        def __init__(self, *args, **kwargs):
            for key, value in zip(fields, args):
                setattr(self, key, value)
            for key, value in kwargs.items():
                setattr(self, key, value)

        def __str__(self):
            return f"{self.__class__.__name__}({', '.join([f'{k}={v}' for k, v in self.__dict__.items() if k not in ['_srid']])})"

        def __repr__(self):
            return str(self)

    Point.__name__ = name

    for field in fields:
        # Add a property for each field if not already present
        if not hasattr(Point, field):
            def property_getter(self, field=field):
                return getattr(self, field)

            def property_setter(self, value, field=field):
                setattr(self, field, value)

            property = property(property_getter, property_setter, doc=field)
            setattr(Point, field, property)

    # Add SRID handling
    Point.srid = None
    Point._srid = None

    @property
    def srid(self):
        return self._srid

    @srid.setter
    def srid(self, value):
        if value not in srid_map:
            raise ValueError(f"Invalid SRID: {value}")
        self._srid = srid_map[value]

    # Example method to use SRID
    def to_wkt(self):
        srid_str = f"SRID={self._srid};" if self._srid is not None else ""
        return f"{srid_str} POINT({self.x} {self.y})"

    # Add the to_wkt method to the class
    Point.to_wkt = MethodType(to_wkt, Point)

    return Point

