    PointClass = type(name, (object,), {})

    # Add fields to the Point class
    for field_name, field_type in fields.items():
        PointClass.__dict__[field_name] = field_type

    # Add SRID mapping functionality
    def srid_mapping(self, srid):
        if srid in srid_map:
            return srid_map[srid]
        else:
