def xargs(cmd: tuple[str, ...], varargs: Sequence[str], *, color: bool = False, target_concurrency: int = 1, _max_length: int = _get_platform_max_length(), **kwargs: Any) -> tuple[int, bytes]:
    """A simplified implementation of xargs.
    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    import os
    import signal
    import subprocess
    from concurrent.futures import ProcessPoolExecutor
    from typing import Sequence, Any, Optional, NamedTuple

    result = subprocess.Popen(cmd + tuple(varargs), **kwargs)

    if color and hasattr(os, 'setsid'):
        os.setsid()

    try:
        with ProcessPoolExecutor(max_workers=target_concurrency) as executor:
            futures = {executor.submit(result.wait, timeout=None): result for result in result.children}
            while futures:
                done, not_done = concurrent.futures.wait(futures, timeout=None)
                for future in done:
                    del futures[future]
                    result.returncode = future.result()
        return result.returncode, result.stdout.read()
    except Exception as e:
        return -1, str(e).encode('utf-8')
    finally:
        for result in futures.values():
            os.killpg(os.getpgid(result.pid), signal.SIGKILL)
        result.wait()

def xargs(cmd, varargs, *, color=False, target_concurrency=1, _max_length=_get_platform_max_length(), **kwargs):
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    result = []
    for arg in varargs:
        result.extend(cmd + (arg,))
    return len(result), b' '.join(result)

