from functools import wraps
import time

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """

    class _TTLCache:
        def __init__(self, maxsize, ttl, timer, typed):
            self.maxsize = maxsize
            self.ttl = ttl
            self.timer = timer
            self.typed = typed
            self.cache = {}
            self.access_times = {}
            self.locks = {}
            self._create_locks()

        def _create_locks(self):
            class Sentinel:
                pass
            self.sentinel = Sentinel()
            self.locks = {i: self.sentinel for i in range(maxsize)}

        def __call__(self, func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                key = (func, args, tuple(kwargs.items())) if not self.typed else args
                with self._get_lock(key[0]):
                    if key in self.cache and self.timer() - self.access_times[key] <= self.ttl:
                        return self.cache[key]
                    result = func(*args, **kwargs)
                    if len(self.cache) >= self.maxsize:
                        with self._get_lock(None):
                            old_key = next(iter(self.access_times))
                            old_access_time = self.access_times[old_key]
                            while any(self.timer() - self.access_times[k] <= self.ttl for k in self.access_times if k is old_key):
                                old_key = next(iter(self.access_times))
                            del self.cache[old_key]
                            del self.access_times[old_key]
                    self.cache[key] = result
                    self.access_times[key] = self.timer()
                    return result
            return wrapper

        def _get_lock(self, key):
            if key is None:
                return self.sentinel
            return self.locks[key % self.maxsize]

    return _TTLCache(maxsize, ttl, timer, typed)
