def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    if maxsize is None:
        maxsize = 0

    cache = {}
    sentinel = object()

    class memoized_func:
        def __init__(self, func, maxsize, typed):
            self.func = func
            self.cache = cache
            self.maxsize = maxsize
            self.typed = typed

        def __call__(self, *args, **kw):
            key = args
            if self.typed:
                key += tuple(type(arg) for arg in args)
            if kw:
                sorted_items = sorted(kw.items())
                key += tuple(sorted_items)

            if key not in self.cache:
                if self.maxsize:
                    self.cache[key] = fnocache(self.func, key, self.maxsize)
                else:
                    self.cache[key] = self.func(*args, **kw)
            return self.cache[key]

    def fnocache(func, key, maxsize):
        result = func(*key)
        if maxsize:
            oldest_key = list(cache.keys())[0]
            del cache[oldest_key]
        return result

    return lambda f: memoized_func(f, maxsize, typed)

