from functools import wraps, singledispatch

class _HashedSeq(dict):
    __slots__ = 'hashvalue'

    def __new__(cls, hashvalue, *args, **kw):
        return dict.__new__(cls, *args, **kw)

    def __init__(self, hashvalue, *args, **kw):
        super().__init__(*args, **kw)
        self.hashvalue = hashvalue

    def __hash__(self):
        return self.hashvalue

def _make_key(args, kwds, typed, kwd_mark=(), fasttypes={int, str, frozenset}):
    key = args
    if kwds:
        sorted_items = sorted(kwds.items())

        key += kwd_mark
        key += tuple(item if isinstance(item, fasttypes) else id(item) for item in sorted_items)
    if typed:
        key += tuple(item.__class__ for item in args)
        if kwds:
            key += tuple(item.__class__ for item in sorted_items)

    return _HashedSeq(hash(key), key)

@singledispatch
def _mru_cache_wrapper(func, wrapper, *, maxsize=128, typed=False, root=True):
    cache = {}
    hider = {}

    getitem = cache.get

    def wrapper(*args, **kwds):
        if root:  # Typically this will be True, except if the called function has hit a recursion limit.
            try:
                cacheproxy = cache.get(hider, args, _HashedSeq)
            except TypeError as e:
                s = f"unhashable type: {e}"
                raise TypeError(s, e.__cause__) from None
            if cacheproxy is not hider:
                cache命中了
                return cacheproxy(*args, **kwds)
            else:
                # 没有命中缓存
                # 计算并放入缓存
                result = func(*args, **kwds)
                cache[hider] = result
                if len(cache) >maxsize:
                    # 删除最旧的项
                    oldest_key = next(iter(cache))
                    del cache[oldest_key]
                return result
        else:
            # 将函数放入申请层
            return func(*args, **kwds)

    wrapper.cache_info = None
    wrapper.cache_clear = None

    return wrapper

_mru_cache_wrapper.register(function_type)(_mru_cache_wrapper)

def mru_cache(maxsize=128, typed=False):
