def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """

    if maxsize == 0:
        return functools._make_decorator({}, lambda func: func)

    class LFUCacheMeta(type):
        def __init__(cls, name, bases, namespace):
            super().__init__(name, bases, namespace)
            cls.cache = {}
            cls.frequency = {}
            cls.maxsize = maxsize

        def __call__(cls, func):
            cache = cls.cache
            frequency = cls.frequency
            maxsize = cls.maxsize

            @functools.wraps(func)
            def wrapper(*args, **kwargs):
                if typed:
                    key = (func, args, tuple(kwargs.items()))
                else:
                    key = (func, args)

                if key not in cache:
                    result = func(*args, **kwargs)
                    cache[key] = (result, 1)
                    if len(cache) > maxsize:
                        lfu_key = min(cache, key=lambda k: (cache[k][1], k))
                        del cache[lfu_key]
                        del frequency[lfu_key]
                else:
                    result, freq = cache[key]
                    frequency[key] = freq + 1

                return result

            return wrapper

    return LFUCacheMeta('LFUCache', (), {})
