import collections

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """

    class LFUCache:
        def __init__(self, maxsize, typed):
            self.cache = collections.OrderedDict()
            self.frequency = collections.defaultdict(collections.Counter)
            self.maxsize = maxsize
            self.typed = typed

        def __call__(self, func):
            def wrapper(*args, **kwargs):
                key = args if not self.typed else (func, args, tuple(kwargs.items()))
                frequency_key = (key, args.count(kwargs))

                if key in self.cache:
                    self.frequency[frequency_key][0] += 1
                else:
                    self.cache[key] = func(*args, **kwargs)
                    self.frequency[frequency_key][0] = 1

                least_frequent_key = min(self.frequency, key=lambda x: x[1][0])
                if len(self.cache) > self.maxsize:
                    del self.cache[least_frequent_key[0]]
                    del self.frequency[least_frequent_key]

                return self.cache[key]
            return wrapper
    return LFUCache(maxsize, typed)
