def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return: The exception readable string
    :rtype: str
    """
    def get_stack(frame, level=0):
        if frame.f_back is None or level >= max_level:
            return []
        return [frame] + get_stack(frame.f_back, level + 1)

    def format_path(path):
        return '/' + '/'.join(path)

    def format_frame(frame):
        return f"{frame.f_code.co_filename}:{frame.f_lineno}"

    def format_exception(e):
        return f"{type(e).__name__}: {e}"

    stack = get_stack(e.__traceback__)
    stack = stack[:max_path_level]
    path = [format_frame(frame) for frame in stack]
    readable_str = format_exception(e) + '\n' + format_path(path)
    return readable_str
