def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """

    def format_stack(stack, level):
        if level <= 0:
            return "..."
        return "\n".join("  " * (level - 1) + frame[0][2:] for frame in stack)

    def format_traceback(traceback, level):
        if not traceback:
            return ""
        return format_stack(traceback, level)

    def format_exception(exc_type, exc_value, exc_traceback, level):
        if level <= 0:
            return "..."
        return f"{exc_type.__name__}: {exc_value}\n{format_stack(exc_traceback, level)}"

    def format_path(path, level):
        if level <= 0:
            return "..."
        return "\n".join("  " * (level - 1) + f"Path: {item}" for item in path)

    exception_message = format_exception(type(e), e, e.__traceback__, max_level)
    traceback_message = format_traceback(e.__traceback__, max_level)
    path_message = format_path(e.__traceback__ and e.__traceback__.tb_frame.f_locals, max_path_level)

    return f"{exception_message}\n\n{traceback_message}\n\n{path_message}"

