def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    # Helper function to determine if class1 is a subclass of class2
    def is_subclass(class1, class2):
        return issubclass(class1, class2)

    # Helper function to remove superfluous classes
    def remove_subclasses(classes):
        result = []
        for cls in classes:
            if not any(is_subclass(cls, other) for other in result):
                result.append(cls)
        return result

    # Sort classes by base class hierarchy
    classes.sort(key=lambda x: (len(x.__bases__), x))
    # Remove superfluous classes
    minimal_classes = remove_subclasses(classes)
    return minimal_classes

