def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    # Sort classes by their type id such that subclasses come after their superclasses
    classes.sort(key=lambda cls: cls.classId)

    # Use a set to keep track of the minimal base classes
    minimal_classes = set()

    for cls in classes:
        # If this class is not a subclass of any previously added class, it's minimal
        if not any(issubclass(cls, c) for c in minimal_classes):
            minimal_classes.add(cls)

    return sorted(minimal_classes, key=lambda cls: cls.classId)
