def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    min_values = {}
    for cls in classes:
        for attr in dir(cls):
            value = getattr(cls, attr)
            if attr.startswith("__"):
                continue
            if attr in min_values:
                min_values[attr] = value if value < min_values[attr] else min_values[attr]
            else:
                min_values[attr] = value

    min_set = set()
    for cls in classes:
        keep = True
        for attr, value in cls.__dict__.items():
            if attr not in min_values:
                continue
            if value != min_values[attr]:
                keep = False
                break
        if keep:
            min_set.add(cls)

    return sorted(list(min_set), key=classes.index)

