        return {}

    result = {}
    for k, v1 in d1.items():
        if k not in d2:
            result[k] = copy.deepcopy(v1)
        elif isinstance(v1, dict) and isinstance(d2[k], dict):
            diff = difference(v1, d2[k], level if level == -1 else level - 1)
