    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise ValueError("Both arguments must be dictionaries")

    if level == 0:
        return {}
    elif level == -1:
        return {k: v for k, v in d1.items() if k not in d2}
    else:
        result = {}
        for k, v in d1.items():
            if k not in d2:
