def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    """Together with :func:`update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """

    for item in observer_schema:
        if isinstance(item, dict) and 'key' in item and 'type' in item:
            key = item['key']
            value_type = item['type']
            if key in response:
                if value_type == 'list':
                    if last_applied_manifest is None:
                        last_applied_manifest = []
                    elif not isinstance(last_applied_manifest, list):
                        raise ValueError("last_applied_manifest should be a list if the type is 'list'")
                    update_last_applied_manifest_list_from_resp(last_applied_manifest, item.get('schema', []), response[key])
                elif value_type == 'dict':
                    if last_applied_manifest is None:
                        last_applied_manifest = {}
                    elif not isinstance(last_applied_manifest, dict):
                        raise ValueError("last_applied_manifest should be a dict if the type is 'dict'")
                    update_last_applied_manifest_list_from_resp(last_applied_manifest, item.get('schema', []), response[key])
                elif value_type == 'string' or value_type == 'integer' or value_type == 'boolean':
                    last_applied_manifest[key] = response[key] if key in response else None
                else:
                    raise ValueError(f"Unsupported value_type: {value_type}")
