def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	The set of converted out-style parameters (:class:`dict` or
        :class:`list`).
    """

    if isinstance(sql, bytes):
        sql = sql.decode('utf-8')

    if isinstance(params, dict):
        if self.SQLParams.in_style == 'named':
            param_mapping = params
        else:
            raise ValueError("params must be a sequence when SQLParams.in_style is 'named'")
    elif isinstance(params, sequence):
        if self.SQLParams.in_style == 'ordinal':
            param_mapping = {i: params[i] for i in range(len(params))}
        else:
            raise ValueError("params must be a dictionary when SQLParams.in_style is 'named'")
    else:
        raise ValueError("params must be a mapping or sequence")

    formatted_sql = sql
    out_style_params: Dict[Union[str, int], Any] = {}

    for key, value in param_mapping.items():
        placeholder = f":{key}" if self.SQLParams*out_style_params[str(key)] = value

    return formatted_sql, out_style_params

def formatmany(self, sql: AnyStr, many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]]) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    out_params_list: Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]] = []

    if not sql or not many_params:
        return sql, out_params_list

    for params in many_params:
        out_params = self.formatone(params)
        out_params_list.append(out_params)

    return sql, out_params_list

def formatone(self, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Union[Dict[Union[str, int], Any], Sequence[Any]]:
    if isinstance(params, dict):
        return {k: self.format_value(v) for k, v in params.items()}
    elif isinstance(params, list):
        return [self.format_value(v) for v in params]
    else:
        raise ValueError("Invalid parameter type. Expected a dictionary or a sequence.")

def format_value(self, value: Any) -> Any:
    if isinstance(value, str):
        return f"{value}"
    elif isinstance(value, bytes):
        return f"b'{value}'"
    elif isinstance(value, bool):
        return "True" if value else "False"
    elif value is None:
        return "NULL"
    else:
        return str(value)

