import os
import hashlib
import shutil

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    if not os.path.exists(path):
        raise FileNotFoundError(f"Path {path} does not exist")

    if os.listdir(path) != ['.ocfl']:
        raise ValueError(f"Invalid OCFL object: {path} does not contain a .ocfl directory")

    ocfl_dir = os.path.join(path, '.ocfl')
    if not os.path.isdir(ocfl_dir):
        raise ValueError(f"Invalid OCFL object: .ocfl directory does not exist in {path}")

    inventory_path = os.path.join(ocfl_dir, 'inventory.json')
    if not os.path.isfile(inventory_path):
        raise ValueError(f"Invalid OCFL object: inventory.json file does not exist in {path}")

    try:
        with open(inventory_path, 'r') as f:
            inventory = json.load(f)
    except json.JSONDecodeError:
        raise ValueError(f"Invalid OCFL object: inventory.json is not a valid JSON file")

    # Validate inventory structure
    if 'manifest' not in inventory or not isinstance(inventory['manifest'], dict):
        raise ValueError(f"Invalid OCFL object: inventory.json does not contain a valid manifest")

    if 'message' not in inventory or not isinstance(inventory['message'], dict):
        raise ValueError(f"Invalid OCFL object: inventory.json does not contain a valid message")

    # Validate message structure
    if 'digest' not in inventory['message'] or not isinstance(inventory['message']['digest'], dict):
        raise ValueError(f"Invalid OCFL object: inventory.json message does not contain a valid digest")

    if 'algorithm' not in inventory['message']['digest'] or not isinstance(inventory['message']['digest']['algorithm'], str):
        raise ValueError(f"Invalid OCFL object: inventory.json message digest does not contain a valid algorithm")

    if 'value' not in inventory['message']['digest'] or not isinstance(inventory['message']['digest']['value'], str):
        raise ValueError(f"Invalid OCFL object: inventory.json message digest does not contain a valid value")

    # Validate manifest
    for identifier, object_entry in inventory['manifest'].items():
        if not isinstance(identifier, str) or not isinstance(object_entry, dict):
            raise ValueError(f"Invalid OCFL object: manifest contains invalid entries")

        if 'format' not in object_entry or not isinstance(object_entry['format'], str):
            raise ValueError(f"Invalid OCFL object: manifest entry {identifier} does not contain a valid format")

        if 'size' not in object_entry or not isinstance(object_entry['size'], int):
            raise ValueError(f"Invalid OCFL object: manifest entry {identifier} does not contain a valid size")

        if 'paths' not in object_entry or not isinstance(object_entry['paths'], list):
            raise ValueError(f"Invalid OCFL object: manifest entry {identifier} does not contain valid paths")

        for path in object_entry['paths']:
            if not isinstance(path, str):
                raise ValueError(f"Invalid OCFL object: manifest entry {identifier} paths contains invalid entries")

            full_path = os.path.join(path, identifier)
            if not os.path.exists(full_path):
                raise ValueError(f"Invalid OCFL object: object {identifier} not found at {full_path}")

            if os.path.getsize(full_path) != object_entry['size']:
                raise ValueError(f"Invalid OCFL object: object {identifier} size does not match manifest")

            with open(full_path, 'rb') as f:
                file_hash = hashlib.sha256(f.read()).hexdigest()

            if file_hash != object_entry['paths']:
                raise ValueError(f"Invalid OCFL object: object {identifier} digest does not match manifest")

    return True
