    if not os.path.isdir(path):
        return False

    inventory_path = os.path.join(path, 'inventory.json')
    if not os.path.exists(inventory_path):
        return False

    try:
        with open(inventory_path, 'r') as f:
            inventory = f.read()
    except Exception as e:
        return False

    try:
        actual_hash = hashlib.sha256(inventory.encode()).hexdigest()
    except Exception as e:
        return False

    inventory_hash_path = os.path.join(path, 'inventory-sha256.txt')
    if not os.path.exists(inventory_hash_path):
        return False

    try:
        with open(inventory_hash_path, 'r') as f:
            expected_hash = f.read().strip()
    except Exception as e:
        return False

    if actual_hash != expected_hash:
        return False

    return True
