def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    try:
        import zipfile
        import os
        data = {}
        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            for file_name in zip_ref.namelist():
                if file_name.endswith('.xml'):
                    xml_base = os.path.splitext(xml_base)[0] # Remove extension
                    if xml_base in data:
                        data[xml_base].append(file_name)
                    else:
                        data[xml_base] = [file_name]
        return data
    except Exception as e:
        print(f"Error exploring zipfile at {zip_path}: {e}")
        return {}

