def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """

    # Determine the prefix for the current level of indentation
    prefix = ' ' * indent

    # Create a string representation of the current node
    if debug:
        result = f"{prefix}{self.__class__.__name__}(\n"
    else:
        result = f"{prefix}{self.__class__.__name__}\n"

    # Add attributes to the result string
    for attr, value in self.__dict__.items():
        if not attr.startswith('_'):  # Skip private attributes
            if debug:
                result += f"{prefix}  {attr}={value}\n"
            else:
                result += f"{prefix}  {attr}: {value}\n"

    # Recursively add child elements
    for child in self.children:
        result += child.pretty(indent + 2, debug)

    if debug:
        result += f"{prefix})\n"

    return result
