                        s.replace('\n', '\n' + col1) for s in (
                            k + ': ' + StringCodec.dumps(v)
                        for k, v in sorted(val.items()))
                    )
            elif isinstance(val, set):
                col1 = '  ' * (indent + 1)
                ret += '\n' + col1 + '\n'.join(
                        s.replace('\n', '\n' + col1) for s in (
                            str(e) for e in sorted(val)))
            elif isinstance(val, (Attribute, Element)):
                ret += '\n%s' % str(val.pretty(indent + 2, True))
            else:
                ret += '\n%s' % str(val)

            retval.append(ret)

        if not callable(method):
