    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def apply_absorption(expr):
        if isinstance(expr, tuple):
            op, left, right = expr
            if op == '&':
                if (isinstance(left, tuple) and left[0] == '|' and left[1] == left[2]) or (isinstance(right, tuple) and right[0] == '|' and right[1] == right[2]):
                    return left if left[0] == '|' else right
            elif op == '|':
                if (isinstance(left, tuple) and left[0] == '&' and left[1] == left[2]) or (isinstance(right, tuple) and right[0] == '&' and right[1] == right[2]):
                    return left if left[0] == '&' else right
        return expr

    def apply_negative_absorption(expr):
        if isinstance(expr, tuple):
            op, left, right = expr
            if op == '&':
                if (isinstance(left, tuple) and left[0] == '|' and len(left) == 3 and left[2] == ('~', left[1])) or (isinstance(right, tuple) and right[0] == '|' and len(right) == 3 and right[2] == ('~', right[1])):
                    return left[1] if left[0] == '|' else right[1]
            elif op == '|':
                if (isinstance(left, tuple) and left[0] == '&' and len(left) == 3 and left[2] == ('~', left[1])) or (isinstance(right, tuple) and right[0] == '&' and len(right) == 3 and right[2] == ('~', right[1])):
                    return left[1] if left[0] == '&' else right[1]
        return expr

    result = []
    for arg in args:
        arg = apply_absorption(arg)
        arg = apply_negative_absorption(arg)
        result.append(arg)
    return result

