    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def apply_absorption(expr1, expr2):
        if expr1 == expr2:
            return expr1
        return None

    def apply_negative_absorption(expr1, expr2):
        if expr1 == (~expr2):
