def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys

    if sys.version_info[0] < 3:
        try:
            import __builtin__ as builtins
        except ImportError:
            import builtins

        original_tzname = builtins.tzname

        def new_tzname():
            return tuple(name.encode('utf-8') if isinstance(name, unicode) else name for name in original_tzname())

        builtins.tzname = new_tzname

    return namefunc()

