def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    root_inventory = None
    content_digests = {}

    for version_dir in version_dirs:
        inventory_path = os.path.join(version_dir, 'inventory')
        if not os.path.exists(inventory_path):
            raise FileNotFoundError(f"Inventory file not found for version {version_dir}")

        with open(inventory_path, 'r') as inventory_file:
            inventory = json.load(inventory_file)

        if not root_inventory:
            root_inventory = inventory
        else:
            for content_id, content_digest in inventory.items():
                if content_id in content_digests:
                    if content_digests[content_id] != content_digest:
                        raise DigestMismatchError(f"Digest mismatch for content ID {content_id} between root inventory and version {version_dir}")
                else:
                    content_digests[content_id] = content_digest

    # Check for missing content digests in the root inventory
    root_inventory_digests = {content_id: content_digests[content_id] for content_id in content_digests if content_id in root_inventory}
    if root_inventory_digests != root_inventory:
        raise DigestMismatchError("Missing content digests in root inventory")

    return True

