    for subparser_name, subparser in subparsers.items():
        try:
            namespace, remaining = subparser.parse_known_args(unparsed_arguments)
            parsed_args[subparser_name] = namespace
            unparsed_arguments = remaining
        except Exception as e:
            # Handle parsing exceptions, e.g., argument conflicts
            print(f"Error parsing arguments for subparser {subparser_name}: {e}")

    return parsed_args, unparsed_arguments

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size (str): A string representing a human readable file size (e.g., '500K')

    Returns:
        int: A decimal representation of file size
    """
    size = size.strip().upper()
    if size.isdigit():
        return int(size)
    elif size.endswith('K'):
        return int(float(size[:-1]) * 1000)
    elif size.endswith('M'):
        return int(float(size[:-1]) * 1000000)
    elif size.endswith('G'):
        return int(float(size[:-1]) * 1073741824)
    elif size.endswith('T'):
        return int(float(size[:-1]) * 1099511627776)
    else:
        raise ValueError("Invalid size format")

