def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    # Split the URL into parts
    parts = url.split('?')
    base_url = parts[0]
    if len(parts) > 1:
        query_string = parts[1]
    else:
        query_string = ''

    # Parse the query string into a dictionary
    query_dict = {}
    if query_string:
        for item in query_string.split('&'):
            key, value = item.split('=')
            query_dict[key] = value

    # Replace the placeholders in the base URL with the corresponding values from url_args
    for key, value in url_args.items():
        base_url = base_url.replace(f'{{{key}}}', value)

    # Reconstruct the URL
    if query_dict:
        new_query_string = '&'.join([f'{key}={value}' for key, value in query_dict.items()])
        return f'{base_url}?{new_query_string}'
    else:
        return base_url

def _replace_url_args(url, url_args):
