def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    try:
        if isinstance(commands, str):
            commands = [commands]

        cmd = [commands[0]] + args

        stderr = subprocess.STDOUT if hide_stderr else subprocess.PIPE

        process = subprocess.Popen(cmd, cwd=cwd, stdout=subprocess.PIPE, stderr=stderr, env=env)
        output, error = process.communicate()

        if verbose:
            print(f"Command: {' '.join(cmd)}")
            print(f"Output: {output.decode()}")
            if error:
                print(f"Error: {error.decode()}")

        return process.returncode, output.decode(), error.decode() if error else None

    except Exception as e:
        if verbose:
            print(f"An error occurred: {e}")
        return -1, None, str(e)

