def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.'''

    import logging
    from configparser import ConfigParser, ParsingError
    import os

    if overrides is None:
        overrides = {}

    config_data = {}
    log_records = []

    for filename in config_filenames:
        try:
            if resolve_env:
                filename = os.path.expandvars(filename)
            parser = ConfigParser()
            with open(filename, 'r') as f:
                parser.read_file(f)

            # Apply overrides
            for section in parser.sections():
                if section in overrides:
                    for key, value in overrides[section].items():
                        parser.set(section, key, value)

            # Validate configuration here if needed

            config_data[filename] = parser

        except FileExistsError as e:
            log_records.append(logging.LogRecord('load_configurations', logging.ERROR, filename, 0, str(e), (), None))
        except FileNotFoundError as e:
            log_records.append(logging.LogRecord('load_configurations', logging.ERROR, filename, 0, str(e), (), None))
        except ParsingError as e:
            log_records.append(logging.LogRecord('load_configurations', logging.ERROR, filename, e.lineno, str(e), (), None))
        except Exception as e:
            log_records.append(logging.LogRecord('load_configurations', logging.ERROR, filename, 0, str(e), (), None))

    return config_data, log_records

