import logging

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import configparser
    import os

    logger = logging.getLogger(__name__)

    config_dict = {}
    parse_errors = []

    for filename in config_filenames:
        if not os.path.exists(filename):
            logger.error(f"Configuration file not found: {filename}")
            parse_errors.append(logging.LogRecord('load_configurations', logging.ERROR, None, None, f"Configuration file not found: {filename}", None, None))
            continue

        config = configparser.ConfigParser()
        config.read(filename)

        try:
            if resolve_env:
                config.resolve()
            config_dict[filename] = dict(config)
        except (configparser.Error, TypeError) as e:
            logger.error(f"Error parsing configuration file {filename}: {e}")
            parse_errors.append(logging.LogRecord('load_configurations', logging.ERROR, None, None, f"Error parsing configuration file {filename}: {e}", None, None))

    if overrides:
        for key, value in overrides.items():
            for filename, config in config_dict.items():
                if key in config:
                    config[key] = value

    return config_dict, parse_errors
