    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if not isinstance(seq, (list, tuple, bytearray, bytes, memoryview)):
        seq = list(seq)
    if bufsize is not None and len(seq) > bufsize:
        seq = seq[:bufsize]
    return seq, type(seq)

