def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    try:
        for attr in iface.__dict__:
            if not tentative:
                if attr == '__dict__':
                    continue
                if attr.startswith('__') and attr.endswith('__'):
                    continue

            if not hasattr(candidate, attr):
                return False

            iface_attr = getattr(iface, attr)
            if not hasattr(iface_attr, '__call__'):
                continue

            candidate_attr = getattr(candidate, attr)
            if not callable(candidate_attr):
                return False

            if not callable(iface_attr):
                return False

            if not isinstance(iface_attr, type):
                return False

            if not issubclass(candidate_attr.__class__, iface_attr):
                return False

        return True
    except AttributeError as e:
        return False

