    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    explicit_mc = explicit_mc or getattr(bases[0], '__metaclass__', None)

    for base in bases:
        base_mc = getattr(base, '__metaclass__', None)
        if explicit_mc is None:
            explicit_mc = base_mc
        elif base_mc is not None and base_mc is not explicit_mc:
            raise TypeError("Metaclass conflict: Can't inherit from both " + explicit_mc.__name__ + " and " + base_mc.__name__ + ".")

