import re
from typing import Set, Tuple, Callable

def find_tags(text: str, replacer: Callable[[str], str] = None) -> Tuple[Set[str], str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    in_code_block = False
    result = []
    for line in text.split('\n'):
        parts = re.split(r'(```[\s\S]*?```)', line)
        for part in parts:
            if part.strip().startswith('```'):
                if part.strip().endswith('```'):
                    in_code_block = not in_code_block
                    result.append(part)
                else:
                    in_code_block = not in_code_block
                    result.append(part)
                    continue
            if in_code_block:
                result.append(part)
                continue
            # Find all tags in the line
            for tag in re.findall(r'\b\w+@\w+\b', part):
                tags.add(tag)
                if replacer:
                    part = part.replace(tag, replacer(tag))
            result.append(part)
    return tags, ''.join(result)

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """

    tags = set()
    code_block = False
    result = []
    current_tag = ""

    for char in text:
        if char == '`':
            code_block = not code_block
        elif not code_block and char in "<>":
            if char == "<":
                current_tag += char
            elif char == ">":
                current_tag += char
                tags.add(current_tag[1:-1].strip())
                current_tag = ""
        elif current_tag:
            current_tag += char

        if replacer and current_tag:
            result.append(replacer(current_tag[1:-1].strip()))
            current_tag = ""
        elif not code_block:
            result.append(char)

    return tags, ''.join(result)

