    # Check if the tag starts with an alphabetic character or underscore
    if not tag[0].isalpha() and tag[0] != '_':
        return False

    # Check if the tag contains only alphabetic characters, digits, underscores, and hyphens
    if not all(char.isalnum() or char == '_' or char == '-' for char in tag):
