def list_of_file_names(settings_dirs, spec_option):
    """Create a list of file names from the given settings directories and specification option.

    Args:
        settings_dirs (list of str): A list of directory paths where the settings files are located.
        spec_option (str): Specification option to filter file names.

    Returns:
        list of str: A list of file names matching the specification option.

    Raises:
        FileNotFoundError: If any of the settings directories do not exist.
        ValueError: If the specification option is invalid.
    """
    file_names = []

    # Validate settings directories
    for settings_dir in settings_dirs:
        if not isinstance(settings_dir, str) or not settings_dir:
            raise ValueError("Each element in settings_dirs must be a non-empty string.")
        if not os.path.isdir(settings_dir):
            raise FileNotFoundError(f"The directory '{settings_dir}' does not exist.")

    # Validate specification option
    if not isinstance(spec_option, str) or not spec_option:
        raise ValueError("The spec_option must be a non-empty string.")

    # Filter file names based on specification option
    for settings_dir in settings_dirs:
        for root, _, files in os.walk(settings_dir):
            for file in files:
                if spec_option in file:
                    file_names.append(os.path.join(root, file))

    return file_names
