def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """

    try:
        include_directives = parser_dict.pop('includes', [])
        for include in include_directives:
            group_name = include.get('group')
            file_path = include.get('file')
            if not group_name or not file_path:
                raise ValueError("Invalid include directive: missing group or file")

            with open(file_path, 'r') as file:
                include_content = file.read()

            # Assuming the include content is a dictionary, merge it with parser_dict
            include_dict = eval(include_content)
            if not isinstance(include_dict, dict):
                raise ValueError("Include content must be a dictionary")

            parser_dict.update(include_dict)

    except FileNotFoundError:
        raise FileNotFoundError(f"Include file not found: {file_path}")
    except Exception as e:
        raise ValueError(f"Error processing include directive: {e}")

    return parser_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """

    if 'include' not in parser_dict:
        return

    include_dir = parser_dict['include']

    for file_path in os.listdir(include_dir):
        if file_path.endswith('.xml'):
            file_path = os.path.join(include_dir, file_path)
            with open(file_path, 'r') as f:
                include_dict = xmltodict.parse(f.read())
            self._merge_dicts(parser_dict, include_dict)

    del parser_dict['include']

def _merge_dicts(self, target, source):
    for k, v in source.items():
        if isinstance(v, dict):
            merger = self._merge_dicts
            node = target.setdefault(k, {})
            if isinstance(node, dict):
                merger(node, v)
            else:
                target[k] = v
        else:
            target[k] = v

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """

    if 'include_dict' in parser_dict:
        include_dict = parser_dict['include_dict']
        for key, value in include_dict.items():
            if key in self.data:
                if isinstance(self.data[key], list):
                    self.data[key].extend(value)
                else:
                    self.data[key] = [self.data[key], value]
            else:
                self.data[key] = value
        del parser_dict['include_dict']

