            key, value = arg.split('=', 1)
            if key.startswith('$'):
                custom_args[key[1:]] = value
            elif key.startswith('--control-'):
                control_args[key[len('--control-'):]] = value
            elif key.startswith('--nested-'):
                nested_args[key[len('--nested-'):]] = value
            else:
                nested_args[key] = value
        else:
            if arg.startswith('$'):
                nested_args[arg[1:]] = True
            elif arg.startswith('--control-'):
                control_args[arg[len('--control-'):]] = True
            elif arg.startswith('--nested-'):
