def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """

    import os

    def _flatten_dict(d, parent_key='', sep='_'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(_flatten_dict(v, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    plugin_spec_path = os.path.join(plugin_dir, 'plugin.json')

    if not os.path.exists(plugin_spec_path):
        raise FileNotFoundError(f"Plugin spec file not found at {plugin_spec_path}")

    import json
    with open(plugin_spec_path, 'r') as f:
        plugin_spec = json.load(f)

    return _flatten_dict(plugin_spec)

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """

    import os
    import json

    flattened_dict = {}

    try:
        spec_file_path = os.path.join(plugin_dir, 'plugin_spec.json')
        with open(spec_file_path, 'r') as file:
            spec_dict = json.load(file)

        def flatten(d, parent_key='', sep='_'):
            for k, v in d.items():
                new_key = f"{parent_key}{sep}{k}" if parent_key else k
                if isinstance(v, dict):
                    flatten(v, new_key, sep)
                else:
                    flattened_dict[new_key] = v

        flatten(spec_dict)
    except FileNotFoundError:
        print(f"Plugin spec file not found at {spec_file_path}")
    except json.JSONDecodeError:
        print(f"Error decoding JSON from {spec_file_path}")

    return flattened_dict

